// showIntroBoard translates paragraphs individually; retain full passages too.
// Each locale deliberately preserves the source paragraph boundaries.
const seen = new Set();
export const DEMO_NARRATION_TRANSLATIONS = Object.freeze(narration.flatMap(row => {
    const paragraphs = row.map(text => text.split('\n\n'));
    const candidates = [row];
    if (paragraphs[0].length > 1) {
        if (!paragraphs.every(parts => parts.length === paragraphs[0].length)) {
            throw new Error('Demo narration translation paragraph mismatch.');
        }
        paragraphs[0].forEach((_paragraph, index) => candidates.push(paragraphs.map(parts => parts[index])));
    }
    return candidates.filter(entry => {
        if (seen.has(entry[0])) return false;
        seen.add(entry[0]);
        return true;
    }).map(entry => Object.freeze(entry));
}));
